(1, NULL, 'js_TCalendar.php', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<script>\r\n\r\n\r\nfunction frm030_load_calendar2(obj_id,e) {\r\n	                                var prev = document.getElementById(obj_id).previousElementSibling;\r\n									var calendar_div = document.getElementById(obj_id).nextElementSibling.id;\r\n									\r\n									\r\n									div_check_if_exists(calendar_div);\r\n									toggle_div(calendar_div,\"\");\r\n									document.getElementById(calendar_div).innerHTML=\"Loading...frmT_Calendar \";  \r\n									\r\n									var today = new Date();\r\n									var dd = today.getDate();\r\n									var mm = today.getMonth() + 1; //January is 0!\r\n									var yyyy = today.getFullYear();\r\n									if (dd < 10) {  dd = \'0\' + dd;}\r\n									if (mm < 10) {  mm = \'0\' + mm;}\r\n									\r\n									$.ajax({\r\n										type : \'GET\',\r\n										url  : \'frmTCalendar\',\r\n										data :  {\r\n												fun:\'showcalendar\',\r\n												embed:\'YES\',\r\n												calendar_div:calendar_div,\r\n												dd:dd,\r\n												mm:mm,\r\n												yy:yyyy,\r\n												text_to_update:prev.id\r\n											},\r\n											success :  function(data)   \r\n											{  document.getElementById(calendar_div).innerHTML=data;\r\n											   frm030_refresh_dt(calendar_div,prev.id,\'set_calendar_date\');											\r\n											}\r\n										});}\r\n										\r\n										\r\n\r\nfunction frm030_load_calendar(text_to_update,calendar_div) {\r\n									div_check_if_exists(calendar_div);\r\n									//var today_mm = d.getMonth();\r\n									//var today_dd = d.getDate().toString();\r\n									//today_mm = (today_mm + 1).toString();\r\n									//if (today_mm.length === 1) {today_mm = \"0\" + today_mm;  }\r\n									//if (today_dd.length === 1) {today_dd = \"0\" + today_dd;  }\r\n									toggle_div(calendar_div,\"\");\r\n									var today = new Date();\r\n									var dd = today.getDate();\r\n									var mm = today.getMonth() + 1; //January is 0!\r\n									var yyyy = today.getFullYear();\r\n									if (dd < 10) {  dd = \'0\' + dd;}\r\n									if (mm < 10) {  mm = \'0\' + mm;}\r\n									\r\n									$.ajax({\r\n										type : \'GET\',\r\n										url  : \'frmTCalendar\',\r\n										data :  {\r\n												fun:\'showcalendar\',\r\n												embed:\'YES\',\r\n												calendar_div:calendar_div,\r\n												dd:dd,\r\n												mm:mm,\r\n												yy:yyyy,\r\n												text_to_update:text_to_update\r\n											},\r\n											success :  function(data)   \r\n											{  document.getElementById(calendar_div).innerHTML=data;\r\n											   frm030_refresh_dt(calendar_div,text_to_update,\'set_calendar_date\');											\r\n											}\r\n										});}\r\n										\r\nfunction frm030_load_calendar_timi(element_id,timi) {\r\n	                                console.log(element_id + \'->\' +timi);\r\n									document.getElementById(element_id).value=timi;    \r\n									if (document.getElementById(element_id).onchange!=null) \r\n										 { document.getElementById(element_id).onchange();    }\r\n\r\n									}		\r\n\r\n\r\nfunction frm030_refresh_dt(calendar_div,text_to_update,what) {\r\n									var dd=parseInt(get_div_in_div_value(calendar_div, \'frm030_dd\'));\r\n									var mm=parseInt(get_div_in_div_value(calendar_div, \'frm030_mm\'));\r\n									var yy=parseInt(get_div_in_div_value(calendar_div, \'frm030_yy\'));\r\n									var calendar_div2=\'#\'+calendar_div;\r\n								\r\n									$(calendar_div2).empty();  \r\n									document.getElementById(calendar_div).innerHTML=\"Loading...\";	\r\n									$.ajax({\r\n										type : \'GET\',\r\n										url  : \'frmTCalendar\',\r\n										data :  {\r\n												fun:\'refresh\',\r\n												embed:\'YES\',\r\n												calendar_div:calendar_div,\r\n												text_to_update:text_to_update,\r\n												what:what,\r\n												dd:dd,\r\n												mm:mm,\r\n												yy:yy\r\n											},\r\n											success :  function(data)   \r\n											{  $(calendar_div2).empty();\r\n											     document.getElementById(calendar_div).innerHTML=data;\r\n											}\r\n										});\r\n								}\r\n    \r\nfunction frm030_change_day(calendar_div,what,how) {\r\n								document.getElementById(\'frm030_what\').value = what;\r\n								if (what==\"dd\") {\r\n									document.getElementById(\'frm030_dd\').value=how;\r\n									toggle_div(calendar_div,\"\"); 	}\r\n							}\r\n\r\n	\r\nfunction frm030_close(calendar_div) {\r\n								toggle_div(calendar_div,\"off\");\r\n							}\r\n\r\n							\r\n</script>\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '', '', '', 0, NULL, NULL, NULL, NULL, NULL, NULL),
