(4, NULL, 'js_TServiceDeltio.php', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<script>\r\n\r\nfunction deltioservice_customer_add_rec() { \r\n			var id=document.getElementById(\'sel_customer_id\').value;\r\n			var defaults=id+\'|\';\r\n\r\n		 $.ajax({                               \r\n				type : \'GET\',                    \r\n				url  : \'frmTServiceDeltio_jx\',     \r\n				data :  {                         \r\n						fun:\'deltioservice_customer_add_rec\',   \r\n 						defaults:defaults, \r\n 						embed:\'YES\'                       \r\n					},    						         \r\n					success :  function(data)      	      \r\n					{  \r\n						  document.getElementById(\'rs_jx\').innerHTML=data;  \r\n						  document.getElementById(\'sel_customer_id\').value=document.getElementById(\'ajax_deltioservice_customer_get_record@id\').value;\r\n						  get_deltioservice_customer_record(\'get_deltioservice_customer_record\');\r\n						  document.getElementById(\'rs_jx\').innerHTML=\"\";\r\n					}    \r\n				});    \r\n			}\r\n\r\n\r\n function get_deltioservice_customer_record(fun) { \r\n         var sel_detail_id=document.getElementById(\'sel_customer_id\').value;  		 \r\n		 $.ajax({                               \r\n				type : \'GET\',                    \r\n				url  : \'frmTServiceDeltio_jx\',     \r\n				data :  {                         \r\n						fun:fun,   \r\n 						sel_detail_id:sel_detail_id, \r\n 						embed:\'YES\'                       \r\n					},    						         \r\n					success :  function(data)      	      \r\n					{  $(\'#rs_get_deltioservice_record\').empty();     \r\n					   document.getElementById(\'rs_jx\').innerHTML=data;  \r\n					   toggle_div(\'deltioservice_customer_add_rec_form\',\'on\');\r\n					   document.getElementById(\'id\').value=document.getElementById(\'ajax_deltioservice_get@id\').value;\r\n					   document.getElementById(\'cus_code\').value=document.getElementById(\'ajax_deltioservice_get@dparalabi\').value;\r\n					   document.getElementById(\'cus_txt\').value=document.getElementById(\'ajax_deltioservice_get@tparalabi\').value;\r\n					   document.getElementById(\'til1\').value=document.getElementById(\'ajax_deltioservice_get@til1\').value;\r\n					   document.getElementById(\'til2\').value=document.getElementById(\'ajax_deltioservice_get@til2\').value;\r\n					   document.getElementById(\'phone1\').value=document.getElementById(\'ajax_deltioservice_get@phone1\').value;\r\n					   document.getElementById(\'phone2\').value=document.getElementById(\'ajax_deltioservice_get@phone2\').value;\r\n					   document.getElementById(\'address\').value=document.getElementById(\'ajax_deltioservice_get@address\').value;\r\n					   document.getElementById(\'city\').value=document.getElementById(\'ajax_deltioservice_get@city\').value;\r\n					   document.getElementById(\'perioxi\').value=document.getElementById(\'ajax_deltioservice_get@perioxi\').value;\r\n\r\n					}    \r\n				});    \r\n			}			\r\n \r\n\r\n\r\n function deltioservice_ypokat_add_rec() { \r\n			var id=document.getElementById(\'sel_ypokat_id\').value;\r\n			var defaults=id+\'|\';\r\n\r\n		 $.ajax({                               \r\n				type : \'GET\',                    \r\n				url  : \'frmTServiceDeltio_jx\',     \r\n				data :  {                         \r\n						fun:\'deltioservice_ypokat_add_rec\',   \r\n 						defaults:defaults, \r\n 						embed:\'YES\'                       \r\n					},    						         \r\n					success :  function(data)      	      \r\n					{  \r\n						  document.getElementById(\'rs_jx\').innerHTML=data;  \r\n						  document.getElementById(\'sel_ypokat_id\').value=document.getElementById(\'ajax_deltioservice_ypokat_get_record@id\').value;\r\n						  get_deltioservice_ypokat_record(\'get_deltioservice_ypokat_record\');\r\n						  document.getElementById(\'rs_jx\').innerHTML=\"\";\r\n					}    \r\n				});    \r\n			}				\r\n\r\n\r\n function get_deltioservice_ypokat_record(fun) { \r\n         var sel_detail_id=document.getElementById(\'sel_ypokat_id\').value;  		 \r\n		 $.ajax({                               \r\n				type : \'GET\',                    \r\n				url  : \'frmTServiceDeltio_jx\',     \r\n				data :  {                         \r\n						fun:fun,   \r\n 						sel_detail_id:sel_detail_id, \r\n 						embed:\'YES\'                       \r\n					},    						         \r\n					success :  function(data)      	      \r\n					{  $(\'#rs_get_deltioservice_record\').empty();     \r\n					   document.getElementById(\'rs_jx\').innerHTML=data;  \r\n					   //document.getElementById(\'rs_href\').innerHTML=document.getElementById(\'rs_jx_href\').innerHTML;  \r\n					   toggle_div(\'deltioservice_ypokat_add_rec_form\',\'on\');\r\n					   document.getElementById(\'id\').value=document.getElementById(\'ajax_deltioservice_get@id\').value;\r\n					   document.getElementById(\'dparalabi\').value=document.getElementById(\'ajax_deltioservice_get@dparalabi\').value;\r\n					   document.getElementById(\'tparalabi\').value=document.getElementById(\'ajax_deltioservice_get@tparalabi\').value;\r\n					   document.getElementById(\'usr_paralabi\').value=document.getElementById(\'ajax_deltioservice_get@usr_paralabi\').value;\r\n					   document.getElementById(\'tr_paralabi\').value=document.getElementById(\'ajax_deltioservice_get@tr_paralabi\').value;\r\n					   document.getElementById(\'is_critical\').value=document.getElementById(\'ajax_deltioservice_get@is_critical\').value;\r\n					   document.getElementById(\'cus_id\').value=document.getElementById(\'ajax_deltioservice_get@cus_id\').value;\r\n					   document.getElementById(\'cus_txt\').value=document.getElementById(\'ajax_deltioservice_get@cus_txt\').value;\r\n					   document.getElementById(\'ypok_id\').value=document.getElementById(\'ajax_deltioservice_get@ypok_id\').value;\r\n					   document.getElementById(\'ypok_txt\').value=document.getElementById(\'ajax_deltioservice_get@ypok_txt\').value;\r\n					   document.getElementById(\'factory\').value=document.getElementById(\'ajax_deltioservice_get@factory\').value;\r\n					   document.getElementById(\'model\').value=document.getElementById(\'ajax_deltioservice_get@model\').value;\r\n					   document.getElementById(\'sn\').value=document.getElementById(\'ajax_deltioservice_get@sn\').value;\r\n					   document.getElementById(\'rem_simioseis\').value=document.getElementById(\'ajax_deltioservice_get@rem_simioseis\').value;\r\n					   document.getElementById(\'rem_paratiriseis\').value=document.getElementById(\'ajax_deltioservice_get@rem_paratiriseis\').value;\r\n					}    \r\n				});    \r\n			}			\r\n \r\n\r\n\r\nfunction antallaktika_deltiou() {\r\n  		 document.getElementById(\'rs_antallaktika_deltiou\').innerHTML=\"\"; 	\r\n 	     var id=document.getElementById(\'id\').value;\r\n		 var defaults=id+\'|\';\r\n		 $.ajax({type : \'GET\',\r\n		 		url  : \'frmTServiceDeltio_jx\',data :  { fun:\'antallaktika_deltiou\',defaults:defaults,embed:\'YES\'},success :  function(data) {  \r\n						  document.getElementById(\'rs_jx\').innerHTML=data;  \r\n						  document.getElementById(\'rs_antallaktika_deltiou\').innerHTML=document.getElementById(\'rs_jx_data\').innerHTML;\r\n						  document.getElementById(\'rs_antallaktika_deltiou_copy2\').innerHTML=document.getElementById(\'rs_jx_data\').innerHTML;\r\n						  document.getElementById(\'rs_jx\').innerHTML=\"\";\r\n					} }); }\r\n\r\nfunction ergasies_deltiou() {\r\n  		 document.getElementById(\'rs_ergasies_deltiou\').innerHTML=\"\"; 	\r\n 	     var id=document.getElementById(\'id\').value;\r\n		 var defaults=id+\'|\';\r\n		 $.ajax({type : \'GET\',\r\n		 		url  : \'frmTServiceDeltio_jx\',data :  { fun:\'ergasies_deltiou\',defaults:defaults,embed:\'YES\'},success :  function(data) {  \r\n						  document.getElementById(\'rs_jx\').innerHTML=data;  \r\n						  document.getElementById(\'rs_ergasies_deltiou\').innerHTML=document.getElementById(\'rs_jx_data\').innerHTML;\r\n						  document.getElementById(\'rs_ergasies_deltiou_copy2\').innerHTML=document.getElementById(\'rs_jx_data\').innerHTML;\r\n						  document.getElementById(\'rs_jx\').innerHTML=\"\";\r\n					} }); }\r\n\r\n function search_1() { \r\n 	        document.getElementById(\'rs_customers\').innerHTML=\"\";\r\n 	        document.getElementById(\'rs_ypok\').innerHTML=\"\";\r\n 	        document.getElementById(\'rs_models\').innerHTML=\"\";\r\n\r\n 	        document.getElementById(\'rs_customers\').style.height = \'400px\';\r\n 	        document.getElementById(\'rs_ypok\').style.height = \'80px\';\r\n 	        document.getElementById(\'rs_models\').style.height = \'80px\';\r\n\r\n			var cus_srch=document.getElementById(\'cus_srch\').value;\r\n			var defaults=cus_srch+\'|\';\r\n		 $.ajax({                               \r\n				type : \'GET\',                    \r\n				url  : \'frmTServiceDeltio_jx\',     \r\n				data :  {                         \r\n						fun:\'search_1\',   \r\n 						defaults:defaults, \r\n 						embed:\'YES\'                       \r\n					},    						         \r\n					success :  function(data)      	      \r\n					{  \r\n						  document.getElementById(\'rs_jx\').innerHTML=data;  \r\n						  document.getElementById(\'rs_customers\').innerHTML=document.getElementById(\'rs_jx_data\').innerHTML;\r\n						  document.getElementById(\'rs_jx\').innerHTML=\"\";\r\n					}    \r\n				});    \r\n			}\r\n\r\n\r\n function search_2() { \r\n 	        document.getElementById(\'rs_ypok\').innerHTML=\"\";\r\n 	        document.getElementById(\'rs_models\').innerHTML=\"\"; 	\r\n\r\n 	        document.getElementById(\'rs_customers\').style.height = \'80px\';\r\n 	        document.getElementById(\'rs_ypok\').style.height = \'400px\';\r\n 	        document.getElementById(\'rs_models\').style.height = \'80px\';\r\n\r\n\r\n 	        var cus1_id=document.getElementById(\'cus1_id\').value;\r\n			var ypok_srch=document.getElementById(\'ypok_srch\').value;\r\n			var defaults=ypok_srch+\'|\'+cus1_id+\'|\';\r\n		 $.ajax({                               \r\n				type : \'GET\',                    \r\n				url  : \'frmTServiceDeltio_jx\',     \r\n				data :  {                         \r\n						fun:\'search_2\',   \r\n 						defaults:defaults, \r\n 						embed:\'YES\'                       \r\n					},    						         \r\n					success :  function(data)      	      \r\n					{  \r\n						  document.getElementById(\'rs_jx\').innerHTML=data;  \r\n						  document.getElementById(\'rs_ypok\').innerHTML=document.getElementById(\'rs_jx_data\').innerHTML;\r\n						  document.getElementById(\'rs_jx\').innerHTML=\"\";\r\n					}    \r\n				});    \r\n			}\r\n\r\n\r\n\r\n function search_3() { \r\n 	        document.getElementById(\'rs_models\').innerHTML=\"\"; 	\r\n 	        var cus2_id=document.getElementById(\'cus2_id\').value;\r\n			var ypok1_id=document.getElementById(\'ypok1_id\').value;\r\n\r\n	        document.getElementById(\'rs_customers\').style.height = \'80px\';\r\n 	        document.getElementById(\'rs_ypok\').style.height = \'80px\';\r\n 	        document.getElementById(\'rs_models\').style.height = \'400px\';\r\n\r\n			var defaults=cus2_id+\'|\'+ypok1_id+\'|\';\r\n		 $.ajax({                               \r\n				type : \'GET\',                    \r\n				url  : \'frmTServiceDeltio_jx\',     \r\n				data :  {                         \r\n						fun:\'search_3\',   \r\n 						defaults:defaults, \r\n 						embed:\'YES\'                       \r\n					},    						         \r\n					success :  function(data)      	      \r\n					{  \r\n						  document.getElementById(\'rs_jx\').innerHTML=data;  \r\n						  document.getElementById(\'rs_models\').innerHTML=document.getElementById(\'rs_jx_data\').innerHTML;\r\n						  document.getElementById(\'rs_jx\').innerHTML=\"\";\r\n					}    \r\n				});    \r\n			}\r\n\r\n function ergasia_search_1() { \r\n 	        document.getElementById(\'rs_ergasies\').innerHTML=\"\"; 	\r\n 	        var ergasia_srch=document.getElementById(\'ergasia_srch\').value;\r\n			var defaults=ergasia_srch+\'|\';\r\n		 $.ajax({                               \r\n				type : \'GET\',                    \r\n				url  : \'frmTServiceDeltio_jx\',     \r\n				data :  {                         \r\n						fun:\'ergasia_search\',   \r\n 						defaults:defaults, \r\n 						embed:\'YES\'                       \r\n					},    						         \r\n					success :  function(data)      	      \r\n					{  \r\n						  document.getElementById(\'rs_jx\').innerHTML=data;  \r\n						  document.getElementById(\'rs_ergasies\').innerHTML=document.getElementById(\'rs_jx_data\').innerHTML;\r\n						  document.getElementById(\'rs_jx\').innerHTML=\"\";\r\n					}    \r\n				});    \r\n			}\r\n			\r\n\r\n function antallaktiko_search_1() { \r\n 	        document.getElementById(\'rs_antallaktika\').innerHTML=\"\"; 	\r\n 	        var ergasia_srch=document.getElementById(\'antallaktiko_srch\').value;\r\n			var defaults=ergasia_srch+\'|\';\r\n		 $.ajax({                               \r\n				type : \'GET\',                    \r\n				url  : \'frmTServiceDeltio_jx\',     \r\n				data :  {                         \r\n						fun:\'antallaktiko_search\',   \r\n 						defaults:defaults, \r\n 						embed:\'YES\'                       \r\n					},    						         \r\n					success :  function(data)      	      \r\n					{  \r\n						  document.getElementById(\'rs_jx\').innerHTML=data;  \r\n						  document.getElementById(\'rs_antallaktika\').innerHTML=document.getElementById(\'rs_jx_data\').innerHTML;\r\n						  document.getElementById(\'rs_jx\').innerHTML=\"\";\r\n					}    \r\n				});    \r\n			}\r\n\r\n function deltioservice_add_rec() { \r\n			var id=document.getElementById(\'id\').value;\r\n			var defaults=id+\'|\';\r\n\r\n		 $.ajax({                               \r\n				type : \'GET\',                    \r\n				url  : \'frmTServiceDeltio_jx\',     \r\n				data :  {                         \r\n						fun:\'add_blank_rec\',   \r\n 						defaults:defaults, \r\n 						embed:\'YES\'                       \r\n					},    						         \r\n					success :  function(data)      	      \r\n					{  \r\n						  document.getElementById(\'rs_jx\').innerHTML=data;  \r\n						  document.getElementById(\'sel_detail_id\').value=document.getElementById(\'ajax_deltioservice_get_record@id\').value;\r\n						  get_deltioservice_record(\'get_deltioservice_record\');\r\n						  document.getElementById(\'rs_jx\').innerHTML=\"\";\r\n					}    \r\n				});    \r\n			}\r\n\r\n function save_deltioservice_rec() { \r\n			var id=document.getElementById(\'id\').value;\r\n			var dparalabi=document.getElementById(\'dparalabi\').value;\r\n			var tparalabi=document.getElementById(\'tparalabi\').value;\r\n			var usr_paralabi=document.getElementById(\'usr_paralabi\').value;\r\n			var tr_paralabi=document.getElementById(\'tr_paralabi\').value;\r\n			var is_critical=document.getElementById(\'is_critical\').value;\r\n			var cus_id=document.getElementById(\'cus_id\').value;\r\n			var cus_txt=document.getElementById(\'cus_txt\').value;\r\n			var ypok_id=document.getElementById(\'ypok_id\').value;\r\n			var ypok_txt=document.getElementById(\'ypok_txt\').value;\r\n			var factory=document.getElementById(\'factory\').value;\r\n			var model=document.getElementById(\'model\').value;\r\n			var sn=document.getElementById(\'sn\').value;\r\n			var rem_simioseis=document.getElementById(\'rem_simioseis\').value;\r\n			var rem_paratiriseis=document.getElementById(\'rem_paratiriseis\').value;\r\n		 $.ajax({                               \r\n				type : \'POST\',                    \r\n				url  : \'frmTServiceDeltio_jx\',     \r\n				data :  {                         \r\n						fun:\'save_pendings\',   \r\n 						id:id, \r\n						dparalabi:dparalabi,\r\n						tparalabi:tparalabi,\r\n						usr_paralabi:usr_paralabi,\r\n						tr_paralabi:tr_paralabi,\r\n						is_critical:is_critical,\r\n						cus_id:cus_id,\r\n						cus_txt:cus_txt,\r\n						ypok_id:ypok_id,\r\n						ypok_txt:ypok_txt,\r\n						factory:factory,\r\n						model:model,\r\n						sn:sn,\r\n						rem_simioseis:rem_simioseis,\r\n 						rem_paratiriseis:rem_paratiriseis,\r\n 						embed:\'YES\'                       \r\n					},    						         \r\n					success :  function(data)      	      \r\n					{  toggle_div(\'deltioservice_add_rec_form\',\'off\');\r\n					}    \r\n				});    \r\n			}\r\n\r\n function get_deltioservice_record(fun) { \r\n         var sel_detail_id=document.getElementById(\'sel_detail_id\').value;  		 \r\n		 $.ajax({                               \r\n				type : \'GET\',                    \r\n				url  : \'frmTServiceDeltio_jx\',     \r\n				data :  {                         \r\n						fun:fun,   \r\n 						sel_detail_id:sel_detail_id, \r\n 						embed:\'YES\'                       \r\n					},    						         \r\n					success :  function(data)      	      \r\n					{  $(\'#rs_get_deltioservice_record\').empty();     \r\n					   document.getElementById(\'rs_jx\').innerHTML=data;  \r\n					   //document.getElementById(\'rs_href\').innerHTML=document.getElementById(\'rs_jx_href\').innerHTML;  \r\n					   toggle_div(\'deltioservice_add_rec_form\',\'on\');\r\n					   document.getElementById(\'id\').value=document.getElementById(\'ajax_deltioservice_get@id\').value;\r\n					   document.getElementById(\'dparalabi\').value=document.getElementById(\'ajax_deltioservice_get@dparalabi\').value;\r\n					   document.getElementById(\'tparalabi\').value=document.getElementById(\'ajax_deltioservice_get@tparalabi\').value;\r\n					   document.getElementById(\'usr_paralabi\').value=document.getElementById(\'ajax_deltioservice_get@usr_paralabi\').value;\r\n					   document.getElementById(\'tr_paralabi\').value=document.getElementById(\'ajax_deltioservice_get@tr_paralabi\').value;\r\n					   document.getElementById(\'is_critical\').value=document.getElementById(\'ajax_deltioservice_get@is_critical\').value;\r\n					   document.getElementById(\'cus_id\').value=document.getElementById(\'ajax_deltioservice_get@cus_id\').value;\r\n					   document.getElementById(\'cus_txt\').value=document.getElementById(\'ajax_deltioservice_get@cus_txt\').value;\r\n					   document.getElementById(\'ypok_id\').value=document.getElementById(\'ajax_deltioservice_get@ypok_id\').value;\r\n					   document.getElementById(\'ypok_txt\').value=document.getElementById(\'ajax_deltioservice_get@ypok_txt\').value;\r\n					   document.getElementById(\'factory\').value=document.getElementById(\'ajax_deltioservice_get@factory\').value;\r\n					   document.getElementById(\'model\').value=document.getElementById(\'ajax_deltioservice_get@model\').value;\r\n					   document.getElementById(\'sn\').value=document.getElementById(\'ajax_deltioservice_get@sn\').value;\r\n					   document.getElementById(\'rem_simioseis\').value=document.getElementById(\'ajax_deltioservice_get@rem_simioseis\').value;\r\n					   document.getElementById(\'rem_paratiriseis\').value=document.getElementById(\'ajax_deltioservice_get@rem_paratiriseis\').value;\r\n					}    \r\n				});    \r\n			}			\r\n\r\nfunction fill_now_date(el) {\r\n		 var today = new Date();\r\n		 var dd=today.getDate()+\"\";\r\n		 var mm=(today.getMonth()+1)+\"\";\r\n		 var yy=today.getFullYear()+\"\";\r\n		 if (dd.length<=1) { dd=\"0\"+dd; }\r\n		 if (mm.length<=1) { mm=\"0\"+mm; }\r\n		 var now_dt = dd+ \"-\" + mm + \"-\" + yy;\r\n		 document.getElementById(el).value=now_dt;\r\n		 }		 \r\n\r\n\r\nfunction toggle_chk(element_id) {    \r\n	     div_check_if_exists(element_id);  \r\n		 new_value=\"?\";\r\n         if (document.getElementById(element_id).value==\"\")    {new_value=\"NAI\"; } \r\n		 if (document.getElementById(element_id).value==\"NAI\") {new_value=\"---\"; } \r\n		 if (document.getElementById(element_id).value==\"---\") {new_value=\"NAI\"; } \r\n		 document.getElementById(element_id).value=new_value;\r\n	}	\r\n\r\n	\r\n</script>	\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '', '', '', 0, NULL, NULL, NULL, NULL, NULL, NULL),
(5, NULL, 'js_TMiniCall.php', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<script>	\n function minicall_add_rec() { \n			var id=document.getElementById(\'id\').value;\n			var afora=document.getElementById(\'afora\').innerHTML;\n			var afora_id=document.getElementById(\'afora_id\').innerHTML;\n			var afora_txt=document.getElementById(\'afora_txt\').innerHTML;\n\n			var defaults=id+\'|\'+afora+\'|\'+afora_id+\'|\'+afora_txt;\n\n		 $.ajax({                               \n				type : \'GET\',                    \n				url  : \'frmTMiniCall_jx\',     \n				data :  {                         \n						fun:\'add_blank_rec\',   \n 						defaults:defaults, \n 						embed:\'YES\'                       \n					},    						         \n					success :  function(data)      	      \n					{  \n						  document.getElementById(\'rs_jx\').innerHTML=data;  \n						  document.getElementById(\'sel_detail_id\').value=document.getElementById(\'ajax_pendings_get_record_id\').value;\n						  get_pendings_record(\'get_pendings_record\');\n						  document.getElementById(\'rs_jx\').innerHTML=\"\";\n					}    \n				});    \n			}\n\n function save_minicall_rec() { \n			var id=document.getElementById(\'id\').value;\n			var afora=document.getElementById(\'afora\').innerHTML;\n			var afora_id=document.getElementById(\'afora_id\').innerHTML;\n			var afora_txt=document.getElementById(\'afora_txt\').innerHTML;\n\n			var darxiki=document.getElementById(\'darxiki\').value;\n			var dteliki=document.getElementById(\'dteliki\').value;\n			var rem_simioseis=document.getElementById(\'rem_simioseis\').value;\n			var rem_paratiriseis=document.getElementById(\'rem_paratiriseis\').value;\n			var is_critical=document.getElementById(\'is_critical\').value;\n\n		 $.ajax({                               \n				type : \'POST\',                    \n				url  : \'frmTMiniCall_jx\',     \n				data :  {                         \n						fun:\'save_pendings\',   \n 						id:id, \n 						afora:afora, \n 						afora_id:afora_id, \n 						afora_txt:afora_txt, \n 						darxiki:darxiki,\n 						dteliki:dteliki,\n 						is_critical:is_critical,\n 						rem_simioseis:rem_simioseis,\n 						rem_paratiriseis:rem_paratiriseis,\n 						embed:\'YES\'                       \n					},    						         \n					success :  function(data)      	      \n					{  toggle_div(\'minicall_add_rec_form\',\'off\');\n					}    \n				});    \n			}\n\n function get_pendings_record(fun) { \n         var sel_detail_id=document.getElementById(\'sel_detail_id\').value;  		 \n		 $.ajax({                               \n				type : \'GET\',                    \n				url  : \'frmTMiniCall_jx\',     \n				data :  {                         \n						fun:fun,   \n 						sel_detail_id:sel_detail_id, \n 						embed:\'YES\'                       \n					},    						         \n					success :  function(data)      	      \n					{  $(\'#rs_get_pendings_record\').empty();     \n					   document.getElementById(\'rs_jx\').innerHTML=data;  \n					   //document.getElementById(\'rs_href\').innerHTML=document.getElementById(\'rs_jx_href\').innerHTML;  \n					   toggle_div(\'minicall_add_rec_form\',\'on\');	\n					   document.getElementById(\'id\').value=document.getElementById(\'ajax_pendings_get_record_id\').value;\n					   document.getElementById(\'afora\').innerHTML=document.getElementById(\'ajax_pendings_get_record_afora\').value;\n					   document.getElementById(\'afora_id\').innerHTML=document.getElementById(\'ajax_pendings_get_record_afora_id\').value;\n					   document.getElementById(\'afora_txt\').innerHTML=document.getElementById(\'ajax_pendings_get_record_afora_txt\').value;\n					   document.getElementById(\'darxiki\').value=document.getElementById(\'ajax_pendings_get_record_darxiki\').value;\n					   document.getElementById(\'dteliki\').value=document.getElementById(\'ajax_pendings_get_record_dteliki\').value;\n					   document.getElementById(\'rem_simioseis\').value=document.getElementById(\'ajax_pendings_get_record_rem_simioseis\').value;\n					   document.getElementById(\'rem_paratiriseis\').value=document.getElementById(\'ajax_pendings_get_record_rem_paratiriseis\').value;\n					}    \n				});    \n			}			\n\nfunction fill_now_date(el) {\n		 var today = new Date();\n		 var dd=today.getDate() ;\n		 var mm=(today.getMonth()+1);\n		 var yy=today.getFullYear();\n		 if (dd.length==1) {dd=\"0\"+dd;}\n		 if (mm.length==1) {mm=\"0\"+mm;}\n\n		 var now_dt = dd+ \"-\" + mm + \"-\" + yy;\n		 document.getElementById(el).value=now_dt;\n		 }		 \n\n\nfunction toggle_chk(element_id) {    \n	     div_check_if_exists(element_id);  \n		 new_value=\"?\";\n         if (document.getElementById(element_id).value==\"\")    {new_value=\"NAI\"; } \n		 if (document.getElementById(element_id).value==\"NAI\") {new_value=\"---\"; } \n		 if (document.getElementById(element_id).value==\"---\") {new_value=\"NAI\"; } \n		 document.getElementById(element_id).value=new_value;\n	}	\n</script>	\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '', '', '', 0, NULL, NULL, NULL, NULL, NULL, NULL);
